import React from "react";

class SpecialistsSection extends React.Component {

  render() {
    const { specialist } = this.props;

    if (!specialist) {
      return null;
    }

    const fullName = `${specialist.first_name || ""} ${
      specialist.last_name || ""
    }`.trim();

    const nextAppointment = specialist.next_appointment;

    return (
      <div className="spec-item">

        {/* ================= TOP ================= */}

        <div className="spec-item-top">

          {/* Avatar */}

          <div className="spec-item-avatar">

            {specialist.avatar ? (
              <img
                src={specialist.avatar}
                alt={fullName}
              />
            ) : (
              <>
                {(specialist.first_name || "").charAt(0)}
                {(specialist.last_name || "").charAt(0)}
              </>
            )}

          </div>


          {/* Info */}

          <div className="spec-item-info">

            <div className="spec-item-name">
              {fullName}
            </div>

            {/* 
              role / سابقه در API فعلی وجود ندارد
              بنابراین فعلاً نمایش داده نمی‌شود.
            */}

          </div>


          {/* Profile */}

          <button className="spec-view-btn">
            مشاهده پروفایل
          </button>

        </div>


        {/* ================= RATING ================= */}

        {/* 
          برای متخصص rating مستقلی در API فعلی نداریم.
          بنابراین این قسمت فعلاً نمایش داده نمی‌شود.
        */}


        {/* ================= NEXT APPOINTMENT ================= */}

        {nextAppointment && (
          <>
            <div className="spec-item-div"></div>

            <div className="spec-item-next">

              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <rect
                  x="3"
                  y="4"
                  width="18"
                  height="18"
                  rx="2"
                />

                <path d="M16 2v4M8 2v4M3 10h18" />
              </svg>


              نوبت بعدی:

              <b>
                {this.formatAppointment(nextAppointment)}
              </b>

            </div>
          </>
        )}

      </div>
    );
  }


  formatAppointment = (appointment) => {

    if (!appointment) {
      return "";
    }

    let date = "";

    if (appointment.appointment_date) {

      const dateObject = new Date(
        appointment.appointment_date
      );

      date = dateObject.toLocaleDateString(
        "fa-IR",
        {
          year: "numeric",
          month: "long",
          day: "numeric",
        }
      );
    }


    let time = "";

    if (appointment.appointment_time) {

      const timeObject = new Date(
        appointment.appointment_time
      );

      time = timeObject.toLocaleTimeString(
        "fa-IR",
        {
          hour: "2-digit",
          minute: "2-digit",
        }
      );
    }


    if (date && time) {
      return `${date}، ساعت ${time}`;
    }

    if (date) {
      return date;
    }

    if (time) {
      return `ساعت ${time}`;
    }

    return "";
  };
}


export default SpecialistsSection;
